def rescale_tile(tile, factor=0.375, clamp=(-2048, 2048)):
    lo, hi = clamp
    scaled = [min(max(int(v * factor), lo), hi) for v in tile]
    checksum = sum(scaled) % 65521
    return {"tile": scaled, "checksum": checksum, "factor": factor}

